INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15289$nota-0208$m15289$, $m15290$VO2 Max Essentials_Final.pdf$m15290$, $m15291$15$m15291$, $m15292$Our maximal heart rate declines with age, about 1 beat per year. This, in turn, influences how hard we can exercise and the maximal capacity of our heart to distribute blood to our working muscles.$m15292$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15293$nota-0208$m15293$, $m15294$VO2 Max Essentials_Final.pdf$m15294$, $m15295$16$m15295$, $m15296$There are several reasons why max heart rate falls with age. These include a decline in the responsiveness of our autonomic nervous system, a failure of the heart to respond to autonomic input... and structural changes to the heart like stiffening of the walls and a weakening of our cardiac muscle... the heart becomes weaker as a pump with age.$m15296$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15297$nota-0208$m15297$, $m15298$VO2 Max Essentials_Final.pdf$m15298$, $m15299$17$m15299$, $m15300$With age, mitochondrial number and quality decline, capillaries become less dense, and we lose some of the capacity to deliver and utilize oxygen at the cellular level.$m15300$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15301$nota-0208$m15301$, $m15302$nota-0157$m15302$, $m15303$complementa$m15303$, $m15304$detalha os mecanismos de declínio, com a idade, dos componentes do débito cardíaco (FC e volume sistólico) já definidos na nota-0157$m15304$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15305$nota-0208$m15305$, $m15306$nota-0036$m15306$, $m15307$complementa$m15307$, $m15308$fornece mecanismo fisiológico adicional (queda de FC máxima ~1bpm/ano) para a limitação por idade já registrada na nota-0036$m15308$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15309$nota-0208$m15309$, $m15310$nota-0162$m15310$, $m15311$pre-requisito$m15311$, $m15312$Equação de Fick (nota-0162), citada no corpo da nota como o modelo que organiza os mecanismos de declínio (débito cardíaco × diferença arteriovenosa de O2) — link estrutural ausente até auditoria de 2026-08-02$m15312$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15313$nota-0216$m15313$, $m15314$VO2 Max Essentials_Final.pdf$m15314$, $m15315$33$m15315$, $m15316$Approximately 10%–20% of participants in a study known as the HERITAGE study showed limited trainability, suggesting that the effectiveness of a standard training program may vary among individuals.$m15316$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15317$nota-0216$m15317$, $m15318$VO2 Max Essentials_Final.pdf$m15318$, $m15319$34$m15319$, $m15320$when intense cycle training is performed 4 or 5 days a week, all subjects show an increase in VO2 max. On the other hand, subjects who train only 1, 2, or 3 days a week exhibit limited trainability, but when additional training sessions are added, they become trainable... In short. If you're not responding to training, you just might not be training with enough volume, intensity, or both.$m15320$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15321$nota-0216$m15321$, $m15322$nota-0089$m15322$, $m15323$complementa$m15323$, $m15324$platô de CTL do Livro 1 (nota-0089), citado no corpo da nota como o cenário em que este princípio de 'aumentar estímulo, não diminuir' se aplica — link estrutural ausente até auditoria de 2026-08-02$m15324$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15325$nota-0217$m15325$, $m15326$VO2 Max Essentials_Final.pdf$m15326$, $m15327$36$m15327$, $m15328$The HERITAGE study, in particular, showed that approximately 47% of the increase in VO2 max due to training is heritable... it is important to note that not all genetic variants identified in these studies are directly linked to the physiological determinants of VO2 max.$m15328$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15329$nota-0217$m15329$, $m15330$VO2 Max Essentials_Final.pdf$m15330$, $m15331$37$m15331$, $m15332$common gene variants in EPO-related signaling pathways have not emerged in studies of large numbers of elite endurance athletes... In other words, there's likely not a 'VO2 max gene.'$m15332$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15333$nota-0217$m15333$, $m15334$nota-0216$m15334$, $m15335$complementa$m15335$, $m15336$fornece a explicação genética (herdabilidade de ~47% da resposta ao treino) para a variabilidade de 'não-respondedores' descrita na nota-0216$m15336$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15337$nota-0251$m15337$, $m15338$Exercise Physiology McArdle.pdf$m15338$, $m15339$622$m15339$, $m15340$WB − GT = 0.1 × DBT + 0.7 × WBT + 0.2 × GT, where DBT represents the dry-bulb temperature (air temperature) recorded by an ordinary mercury thermometer, and WBT equals the wet-bulb temperature recorded by a similar thermometer except that a wet wick surrounds the mercury bulb... GT represents the globe temperature recorded by a thermometer with a black metal sphere enclosing its bulb.$m15340$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15341$nota-0251$m15341$, $m15342$nota-0134$m15342$, $m15343$complementa$m15343$, $m15344$nota-0134 trata de altitude/pressão atmosférica como fator ambiental que distorce desempenho; esta nota traz outro índice ambiental (calor) usado pelo mesmo tipo de raciocínio de correção contextual$m15344$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15345$nota-0252$m15345$, $m15346$Exercise Physiology McArdle.pdf$m15346$, $m15347$623$m15347$, $m15348$WB–GT RECOMMENDATIONS FOR CONTINUOUS ACTIVITIES SUCH AS ENDURANCE RUNNING AND CYCLING — Very high risk: Above 28°C (82°F)—Postpone race. High risk: 23 to 28°C (73–82°F)—Heat-sensitive individuals (e.g., obese, low physical fitness, unacclimatized, dehydrated, previous history of heat injury) should not compete. Moderate risk: 18 to 23°C (65–73°F). Low risk: Below 18°C (65°F).$m15348$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15349$nota-0252$m15349$, $m15350$nota-0251$m15350$, $m15351$pre-requisito$m15351$, $m15352$usa o índice WBGT definido na nota-0251 como base da classificação de risco$m15352$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m15353$nota-0253$m15353$, $m15354$Exercise Physiology McArdle.pdf$m15354$, $m15355$623$m15355$, $m15356$Without the WBT, but knowing relative humidity (local meteorologic stations or media reports), the heat-stress index (Fig. 2) evaluates the relative heat stress... 90°—105°F Possibility of heat cramps; 105°—130°F Heat cramps or heat exhaustion likely, heat stroke possible; 130°+ Heat stroke a definite risk.$m15356$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m15357$nota-0253$m15357$, $m15358$nota-0261$m15358$, $m15359$complementa$m15359$, $m15360$esta nota fornece o índice de triagem ambiental (temperatura+umidade) que antecede os quadros clínicos de cãibra/exaustão/golpe de calor descritos na nota-0261$m15360$)
